self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET'||new URL(req.url).origin!==self.location.origin)return;event.respondWith((async()=>{const cached=await caches.match(req);if(cached)return cached;try{const response=await fetch(req);return response;}catch(error){if(req.mode==='navigate')return (await caches.open(CACHE)).match(new URL('./',self.registration.scope).href);return Response.error();}})());});
